import java.util.*;
import java.lang.Math;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] inputAsType = inputAsType(sc, Integer.class);
        int n = inputAsType[0];
        int mod = inputAsType[1];

        List<Long> sequence = new ArrayList<>();
        sequence.add(0L);
        sequence.add(1L);
        long totalSum = 1L;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long currentSum = totalSum;
            for (int f = 2; f < limit; f++) {
                currentSum = addModulo(currentSum, sequence.get(i / f), mod);
            }
            int boundary = i;
            for (int j = 1; j <= i / limit; j++) {
                int val = i / (j + 1);
                currentSum = addModulo(currentSum, multiplyModulo(boundary - val, sequence.get(j), mod), mod);
                boundary = val;
            }
            totalSum = addModulo(totalSum, currentSum, mod);
            sequence.add(currentSum);
        }
        System.out.println(sequence.get(sequence.size() - 1));
        sc.close();
    }

    private static int[] inputAsType(Scanner sc, Class<Integer> clazz) {
        String[] parts = sc.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    private static long addModulo(long a, long b, int mod) {
        return (a + b) % mod;
    }

    private static long multiplyModulo(long a, long b, int mod) {
        return (a * b) % mod;
    }
}
